/**
 * WEGO SHIIIP transactional email design system.
 *
 * One responsive, table-based shell is shared by every customer email so the brand stays consistent:
 * deep forest frame, cream card, signal-yellow rule, glossy logo, bold display headings and amber CTAs.
 * Styles are inline (required by Gmail/Outlook); a small <style> block only adds mobile stacking.
 *
 * Plain text remains the source of truth for deliverability and for the `email_outbox.body_text` log.
 * HTML is generated by the templates and stored alongside it (`body_html`).
 */

export const EMAIL_COLORS = {
  ink: "#0d0f0e",
  inkSoft: "#454b47",
  cream: "#fcfcf9",
  sand: "#f2f1ea",
  brand: "#12392b",
  brandDeep: "#0b2619",
  amber: "#f7c416",
  amberDeep: "#dcaa00",
  line: "#e4e3da",
  white: "#ffffff",
  amberTint: "#fff8db",
  greenTint: "#eaf3ee",
} as const;

const DISPLAY = "'Bricolage Grotesque','Trebuchet MS','Segoe UI',Helvetica,Arial,sans-serif";
const SANS = "'Plus Jakarta Sans','Segoe UI',Helvetica,Arial,sans-serif";
const MONO = "'JetBrains Mono',ui-monospace,SFMono-Regular,Menlo,Consolas,monospace";

/** HTML-escape untrusted values before they enter the email markup. */
export function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}

export function defaultSiteUrl(env: NodeJS.ProcessEnv = process.env): string {
  return (env.NEXT_PUBLIC_SITE_URL?.trim() || "https://www.wegoshiiip.com").replace(/\/+$/, "");
}

function normalizeSiteUrl(siteUrl?: string): string {
  return (siteUrl?.trim() || defaultSiteUrl()).replace(/\/+$/, "");
}

export function brandLogoUrl(siteUrl?: string): string {
  return `${normalizeSiteUrl(siteUrl)}/brand/wego-shiiip-logo.png`;
}

function supportEmail(env: NodeJS.ProcessEnv = process.env): string {
  return env.SUPPORT_EMAIL?.trim() || env.EMAIL_REPLY_TO?.trim() || "support@wegoshiiip.com";
}

// ───────────────────────── primitives ─────────────────────────

export function p(text: string): string {
  return `<p style="margin:0 0 16px;font-family:${SANS};font-size:16px;line-height:1.65;color:${EMAIL_COLORS.inkSoft}">${escapeHtml(text)}</p>`;
}

/** Paragraph whose inner HTML is already trusted (built with the helpers below). */
export function phtml(html: string): string {
  return `<p style="margin:0 0 16px;font-family:${SANS};font-size:16px;line-height:1.65;color:${EMAIL_COLORS.inkSoft}">${html}</p>`;
}

export function h2(text: string): string {
  return `<h2 style="margin:28px 0 10px;font-family:${DISPLAY};font-size:19px;line-height:1.3;letter-spacing:-0.2px;color:${EMAIL_COLORS.ink}">${escapeHtml(text)}</h2>`;
}

export function label(text: string): string {
  return `<p style="margin:0 0 8px;font-family:${SANS};font-size:10px;font-weight:800;letter-spacing:1.6px;text-transform:uppercase;color:${EMAIL_COLORS.inkSoft}">${escapeHtml(text)}</p>`;
}

export function link(href: string, text: string, tone: "amber" | "ink" = "ink"): string {
  const color = tone === "amber" ? EMAIL_COLORS.amberDeep : EMAIL_COLORS.ink;
  return `<a href="${escapeHtml(href)}" style="color:${color};font-weight:700;text-decoration:underline;text-underline-offset:2px">${escapeHtml(text)}</a>`;
}

export function button(href: string, text: string, variant: "amber" | "dark" | "ghost" = "amber"): string {
  const bg = variant === "amber" ? EMAIL_COLORS.amber : variant === "dark" ? EMAIL_COLORS.brand : EMAIL_COLORS.cream;
  const fg = variant === "amber" ? EMAIL_COLORS.ink : variant === "dark" ? EMAIL_COLORS.white : EMAIL_COLORS.ink;
  const border = variant === "ghost" ? `1px solid ${EMAIL_COLORS.line}` : "0";
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 4px;border-collapse:separate">
  <tr><td align="center" bgcolor="${bg}" style="border-radius:999px;border:${border};mso-padding-alt:14px 26px">
    <a href="${escapeHtml(href)}" style="display:inline-block;padding:14px 26px;font-family:${SANS};font-size:12px;font-weight:800;letter-spacing:0.9px;text-transform:uppercase;color:${fg};text-decoration:none;border-radius:999px">${escapeHtml(text)}</a>
  </td></tr>
</table>`;
}

export function divider(): string {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:26px 0"><tr><td style="border-top:1px solid ${EMAIL_COLORS.line};font-size:0;line-height:0">&nbsp;</td></tr></table>`;
}

export function note(html: string, tone: "amber" | "green" | "muted" = "amber"): string {
  const bg = tone === "amber" ? EMAIL_COLORS.amberTint : tone === "green" ? EMAIL_COLORS.greenTint : EMAIL_COLORS.sand;
  const bar = tone === "amber" ? EMAIL_COLORS.amber : tone === "green" ? EMAIL_COLORS.brand : EMAIL_COLORS.line;
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:18px 0;border-collapse:separate;background:${bg};border-left:4px solid ${bar};border-radius:0 12px 12px 0">
  <tr><td style="padding:14px 16px;font-family:${SANS};font-size:14px;line-height:1.6;color:${EMAIL_COLORS.inkSoft}">${html}</td></tr>
</table>`;
}

export function panel(html: string, tone: "sand" | "green" | "white" = "sand"): string {
  const bg = tone === "green" ? EMAIL_COLORS.brand : tone === "white" ? EMAIL_COLORS.white : EMAIL_COLORS.sand;
  const fg = tone === "green" ? EMAIL_COLORS.white : EMAIL_COLORS.ink;
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:16px 0;border-collapse:separate;background:${bg};border:1px solid ${tone === "green" ? EMAIL_COLORS.brand : EMAIL_COLORS.line};border-radius:16px">
  <tr><td style="padding:20px;font-family:${SANS};font-size:15px;line-height:1.6;color:${fg}">${html}</td></tr>
</table>`;
}

// ───────────────────────── data blocks ─────────────────────────

export interface EmailItem {
  name: string;
  variant?: string;
  quantity: number;
  /** Formatted line total. Omit for lists that show quantities only. */
  amount?: string;
}

export function itemTable(items: EmailItem[]): string {
  if (!items.length) return "";
  const rows = items
    .map((item, index) => {
      const last = index === items.length - 1;
      const border = `border-bottom:${last ? "0" : `1px dashed ${EMAIL_COLORS.line}`}`;
      const variant = item.variant && item.variant !== "Default" ? `<span style="display:block;margin-top:3px;font-family:${SANS};font-size:12px;color:${EMAIL_COLORS.inkSoft}">${escapeHtml(item.variant)}</span>` : "";
      const amount = item.amount
        ? `<td align="right" valign="top" style="padding:13px 0 13px 14px;${border};font-family:${SANS};font-size:15px;font-weight:700;color:${EMAIL_COLORS.ink};white-space:nowrap">${escapeHtml(item.amount)}</td>`
        : "";
      return `<tr>
  <td style="padding:13px 0;${border};font-family:${SANS};font-size:15px;line-height:1.4;font-weight:700;color:${EMAIL_COLORS.ink}">${escapeHtml(item.name)}${variant}</td>
  <td align="right" valign="top" style="padding:13px 0 13px 12px;${border};font-family:${MONO};font-size:13px;color:${EMAIL_COLORS.inkSoft};white-space:nowrap">×${item.quantity}</td>
  ${amount}
</tr>`;
    })
    .join("");
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse">${rows}</table>`;
}

export interface EmailTotal {
  label: string;
  value: string;
  emphasis?: boolean;
  muted?: boolean;
}

export function totalsTable(rows: EmailTotal[]): string {
  const body = rows
    .map((row) => {
      const weight = row.emphasis ? 800 : 500;
      const size = row.emphasis ? 18 : 14;
      const color = row.muted ? EMAIL_COLORS.inkSoft : EMAIL_COLORS.ink;
      const border = row.emphasis ? `border-top:2px solid ${EMAIL_COLORS.ink};padding-top:12px;` : "";
      return `<tr>
  <td style="padding:5px 0;${border}font-family:${SANS};font-size:${size}px;font-weight:${weight};color:${color}">${escapeHtml(row.label)}</td>
  <td align="right" style="padding:5px 0;${border}font-family:${SANS};font-size:${size}px;font-weight:${weight};color:${color};white-space:nowrap">${escapeHtml(row.value)}</td>
</tr>`;
    })
    .join("");
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:14px 0 4px;border-collapse:collapse">${body}</table>`;
}

export function detailRows(rows: { label: string; value: string }[]): string {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse">${rows
    .map((row, index) => `<tr>
  <td style="padding:8px 0;border-top:${index === 0 ? "0" : `1px solid ${EMAIL_COLORS.line}`};font-family:${SANS};font-size:13px;color:${EMAIL_COLORS.inkSoft};vertical-align:top;width:42%">${escapeHtml(row.label)}</td>
  <td style="padding:8px 0;border-top:${index === 0 ? "0" : `1px solid ${EMAIL_COLORS.line}`};font-family:${SANS};font-size:13px;font-weight:700;color:${EMAIL_COLORS.ink};vertical-align:top">${escapeHtml(row.value)}</td>
</tr>`)
    .join("")}</table>`;
}

export function twoCols(left: string, right: string): string {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:16px 0;border-collapse:separate">
  <tr>
    <td class="stack" width="50%" valign="top" style="padding:0 6px 0 0">${left}</td>
    <td class="stack" width="50%" valign="top" style="padding:0 0 0 6px">${right}</td>
  </tr>
</table>`;
}

export function addressCard(title: string, lines: string[]): string {
  const body = lines.filter(Boolean).map((line) => escapeHtml(line)).join("<br>");
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${EMAIL_COLORS.sand};border:1px solid ${EMAIL_COLORS.line};border-radius:14px;border-collapse:separate">
  <tr><td style="padding:16px 18px">
    <p style="margin:0 0 8px;font-family:${SANS};font-size:10px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;color:${EMAIL_COLORS.inkSoft}">${escapeHtml(title)}</p>
    <p style="margin:0;font-family:${SANS};font-size:14px;line-height:1.6;color:${EMAIL_COLORS.ink}">${body}</p>
  </td></tr>
</table>`;
}

export function orderHero(orderNumber: number, total: string, meta?: string): string {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:20px 0 6px;background:${EMAIL_COLORS.brand};border-radius:18px;border-collapse:separate">
  <tr>
    <td class="stack" valign="middle" style="padding:22px 24px">
      <p style="margin:0 0 6px;font-family:${SANS};font-size:10px;font-weight:800;letter-spacing:1.6px;text-transform:uppercase;color:${EMAIL_COLORS.amber}">Order number</p>
      <p style="margin:0;font-family:${MONO};font-size:28px;line-height:1.1;font-weight:700;color:${EMAIL_COLORS.white}">#${orderNumber}</p>
    </td>
    <td class="stack" align="right" valign="middle" style="padding:22px 24px">
      <p style="margin:0 0 6px;font-family:${SANS};font-size:10px;font-weight:800;letter-spacing:1.6px;text-transform:uppercase;color:${EMAIL_COLORS.amber}">${escapeHtml(meta ?? "Total")}</p>
      <p style="margin:0;font-family:${DISPLAY};font-size:24px;line-height:1.1;font-weight:800;color:${EMAIL_COLORS.white};white-space:nowrap">${escapeHtml(total)}</p>
    </td>
  </tr>
</table>`;
}

export function trackingCard(p: { carrier: string; trackingNumber: string; trackingUrl?: string | null }): string {
  const track = p.trackingUrl ? button(p.trackingUrl, "Track parcel", "dark") : "";
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:12px 0;background:${EMAIL_COLORS.white};border:1px solid ${EMAIL_COLORS.line};border-left:4px solid ${EMAIL_COLORS.amber};border-radius:0 14px 14px 0;border-collapse:separate">
  <tr><td style="padding:16px 18px">
    <p style="margin:0 0 4px;font-family:${SANS};font-size:10px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;color:${EMAIL_COLORS.inkSoft}">${escapeHtml(p.carrier)}</p>
    <p style="margin:0 0 6px;font-family:${MONO};font-size:16px;font-weight:700;color:${EMAIL_COLORS.ink};word-break:break-all">${escapeHtml(p.trackingNumber)}</p>
    ${track}
  </td></tr>
</table>`;
}

export function steps(items: { title: string; body: string }[]): string {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse">${items
    .map((item, index) => `<tr>
  <td width="34" valign="top" style="padding:${index === 0 ? "0" : "12px"} 0 0">
    <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td width="24" height="24" align="center" bgcolor="${EMAIL_COLORS.amber}" style="width:24px;height:24px;border-radius:12px;font-family:${SANS};font-size:12px;font-weight:800;color:${EMAIL_COLORS.ink};line-height:24px">${index + 1}</td></tr></table>
  </td>
  <td valign="top" style="padding:${index === 0 ? "1px" : "13px"} 0 0;font-family:${SANS};font-size:14px;line-height:1.6;color:${EMAIL_COLORS.inkSoft}">
    <strong style="color:${EMAIL_COLORS.ink}">${escapeHtml(item.title)}</strong> ${escapeHtml(item.body)}
  </td>
</tr>`)
    .join("")}</table>`;
}

// ───────────────────────── shell ─────────────────────────

export interface EmailShell {
  subject: string;
  preheader?: string;
  eyebrow?: string;
  heading: string;
  intro?: string;
  /** Trusted HTML built with the helpers above. */
  content?: string;
  siteUrl?: string;
  /** Override the reason-for-receipt line in the footer. */
  footerNote?: string;
  /** Internal mail (contact form) uses a shorter footer without storefront links. */
  internal?: boolean;
}

export function renderEmail(o: EmailShell): string {
  const site = normalizeSiteUrl(o.siteUrl);
  const support = supportEmail();
  const year = new Date().getFullYear();
  const preheader = o.preheader ?? `${o.heading} — WEGO SHIIIP`;
  const eyebrow = o.eyebrow
    ? `<p style="margin:0 0 14px"><span style="display:inline-block;background:${EMAIL_COLORS.amber};border-radius:999px;padding:6px 12px;font-family:${SANS};font-size:10px;font-weight:800;letter-spacing:1.3px;text-transform:uppercase;color:${EMAIL_COLORS.ink}">${escapeHtml(o.eyebrow)}</span></p>`
    : "";
  const footerLinks = o.internal
    ? `<p style="margin:0;font-family:${SANS};font-size:12px;line-height:1.6;color:${EMAIL_COLORS.inkSoft}">Internal notification from the WEGO SHIIIP storefront.</p>`
    : `<p style="margin:0;font-family:${SANS};font-size:12px;line-height:1.9;color:${EMAIL_COLORS.inkSoft}">
        <a href="${site}/contact" style="color:${EMAIL_COLORS.ink};font-weight:700;text-decoration:none">Help</a>
        <span style="color:${EMAIL_COLORS.line}"> · </span>
        <a href="${site}/account/orders" style="color:${EMAIL_COLORS.ink};font-weight:700;text-decoration:none">Orders</a>
        <span style="color:${EMAIL_COLORS.line}"> · </span>
        <a href="${site}/pages/returns" style="color:${EMAIL_COLORS.ink};font-weight:700;text-decoration:none">Returns</a>
        <span style="color:${EMAIL_COLORS.line}"> · </span>
        <a href="${site}/withdraw" style="color:${EMAIL_COLORS.ink};font-weight:700;text-decoration:none">Withdraw</a>
      </p>`;

  return `<!doctype html>
<html lang="en" dir="ltr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="x-apple-disable-message-reformatting">
<meta name="color-scheme" content="light only">
<meta name="supported-color-schemes" content="light only">
<title>${escapeHtml(o.subject)}</title>
<style>
  :root { color-scheme: light only; supported-color-schemes: light only; }
  body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }
  table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
  img { -ms-interpolation-mode: bicubic; border: 0; outline: none; text-decoration: none; }
  @media only screen and (max-width: 620px) {
    .wrap { width: 100% !important; max-width: 100% !important; }
    .pad { padding-left: 22px !important; padding-right: 22px !important; }
    .h1 { font-size: 27px !important; line-height: 1.15 !important; }
    .stack { display: block !important; width: 100% !important; box-sizing: border-box !important; }
    .stack + .stack { padding: 12px 0 0 !important; }
    .stack-right { text-align: left !important; }
    .hide-mobile { display: none !important; }
    .btn a { display: block !important; }
  }
</style>
</head>
<body style="margin:0;padding:0;background:${EMAIL_COLORS.brandDeep};">
<div style="display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;color:transparent">${escapeHtml(preheader)}${"&nbsp;&zwnj;".repeat(20)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${EMAIL_COLORS.brandDeep};border-collapse:collapse">
  <tr><td align="center" style="padding:30px 12px 36px">
    <table role="presentation" class="wrap" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;border-collapse:separate">
      <tr>
        <td style="padding:0 4px 18px">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse"><tr>
            <td align="left" valign="middle">
              <a href="${site}" style="text-decoration:none"><img src="${brandLogoUrl(site)}" width="168" alt="WEGO SHIIIP" style="display:block;width:168px;max-width:168px;height:auto;border:0"></a>
            </td>
            <td class="hide-mobile" align="right" valign="middle" style="font-family:${SANS};font-size:9px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:rgba(255,255,255,0.62)">
              Happy Family, Happy Animals
            </td>
          </tr></table>
        </td>
      </tr>
      <tr>
        <td style="background:${EMAIL_COLORS.cream};border-radius:22px;overflow:hidden">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse">
            <tr><td style="height:6px;background:${EMAIL_COLORS.amber};font-size:0;line-height:0">&nbsp;</td></tr>
            <tr><td class="pad" style="padding:34px 40px 38px">
              ${eyebrow}
              <h1 class="h1" style="margin:0 0 14px;font-family:${DISPLAY};font-size:32px;line-height:1.12;letter-spacing:-0.9px;font-weight:800;color:${EMAIL_COLORS.ink}">${escapeHtml(o.heading)}</h1>
              ${o.intro ? p(o.intro) : ""}
              ${o.content ?? ""}
            </td></tr>
            <tr><td style="padding:0 40px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="border-top:1px solid ${EMAIL_COLORS.line};font-size:0;line-height:0">&nbsp;</td></tr></table></td></tr>
            <tr><td class="pad" style="padding:22px 40px 26px;background:${EMAIL_COLORS.sand};border-radius:0 0 22px 22px">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse"><tr>
                <td class="stack" valign="top" style="padding:0 10px 0 0">
                  <p style="margin:0 0 3px;font-family:${SANS};font-size:10px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;color:${EMAIL_COLORS.inkSoft}">Need a hand?</p>
                  <p style="margin:0;font-family:${SANS};font-size:13px;line-height:1.6;color:${EMAIL_COLORS.inkSoft}">Reply to this email or write to <a href="mailto:${escapeHtml(support)}" style="color:${EMAIL_COLORS.ink};font-weight:700;text-decoration:none">${escapeHtml(support)}</a></p>
                </td>
                <td class="stack stack-right" align="right" valign="top" style="padding:4px 0 0 10px">${footerLinks}</td>
              </tr></table>
              <p style="margin:14px 0 0;font-family:${SANS};font-size:11px;line-height:1.6;color:${EMAIL_COLORS.inkSoft}">${escapeHtml(o.footerNote ?? "You received this email because you placed an order at WEGO SHIIIP.")}</p>
            </td></tr>
          </table>
        </td>
      </tr>
      <tr><td align="center" style="padding:18px 8px 0;font-family:${SANS};font-size:10px;line-height:1.7;letter-spacing:0.3px;color:rgba(255,255,255,0.55)">
        © ${year} WEGO SHIIIP · Italy · <a href="${site}" style="color:rgba(255,255,255,0.75);text-decoration:none">wegoshiiip.com</a><br>
        <span style="color:${EMAIL_COLORS.amber}">Happy Family, Happy Animals</span>
      </td></tr>
    </table>
  </td></tr>
</table>
</body>
</html>`;
}

// ───────────────────────── plain-text fallback ─────────────────────────

function linkifyLine(line: string): string {
  const escaped = escapeHtml(line);
  return escaped.replace(/\b(https?:\/\/[^\s<]+)/g, (match) => {
    const trailing = match.match(/[.,;:!?)]+$/)?.[0] ?? "";
    const url = trailing ? match.slice(0, -trailing.length) : match;
    return `<a href="${url}" style="color:${EMAIL_COLORS.brand};font-weight:700;text-decoration:underline">${url}</a>${trailing}`;
  });
}

/**
 * Branded HTML from a plain-text body. Used for legacy outbox rows and generic admin messages.
 * Paragraphs are split on blank lines; bullet lines become a list; URLs become links.
 */
export function textToHtml(subject: string, text: string, siteUrl?: string): string {
  const cleaned = text.replace(/\n*WEGO SHIIIP · Happy Family, Happy Animals\s*$/i, "").trim();
  const blocks = cleaned.split(/\n{2,}/).map((block) => {
    const lines = block.split("\n").filter((line) => line.trim() !== "");
    if (lines.length && lines.every((line) => /^\s*[•\-]\s+/.test(line))) {
      const items = lines
        .map((line) => `<li style="margin:0 0 7px">${linkifyLine(line.replace(/^\s*[•\-]\s+/, ""))}</li>`)
        .join("");
      return `<ul style="margin:0 0 16px;padding-left:20px;font-family:${SANS};font-size:16px;line-height:1.65;color:${EMAIL_COLORS.inkSoft}">${items}</ul>`;
    }
    return `<p style="margin:0 0 16px;font-family:${SANS};font-size:16px;line-height:1.65;color:${EMAIL_COLORS.inkSoft}">${lines.map(linkifyLine).join("<br>")}</p>`;
  });
  return renderEmail({
    subject,
    heading: subject,
    preheader: subject,
    content: blocks.join(""),
    siteUrl,
  });
}
